import { execFile } from "node:child_process";
import { readFile } from "node:fs/promises";
import { promisify } from "node:util";

const run = promisify(execFile);
const git = (...args: string[]) => run("git", args);
const task = JSON.parse(await readFile("task.json", "utf8"));
const branch = `nova/${task.jiraKey}`;

const branchExists = async () => {
  try {
    await git("rev-parse", "--verify", "--quiet", `refs/heads/${branch}`);
    return true;
  } catch (error) {
    if ((error as { code?: unknown }).code === 1) return false;
    throw error;
  }
};

if (await branchExists()) await git("switch", branch);
else await git("switch", "-c", branch);
console.log("on", (await git("branch", "--show-current")).stdout.trim());
